                if a_missing != b_missing:
                    return 1 if a_missing else -1
                continue
            if a != b:
                result = -1 if a < b else 1
                return -result if descending else result
        return 0

    from functools import cmp_to_key
    return sorted(records, key=cmp_to_key(compare))

